-- 0001_init.sql — initial schema for the MERN marketplace on PostgreSQL/Neon.
-- Replaces models/{User,Store,Product,Order,Review,Settings,Message}.js.
--
-- Conventions:
--   * uuid primary keys generated by gen_random_uuid() (pgcrypto / built-in).
--     The API keeps exposing them as `_id` so the existing React client is
--     unaffected by the storage change.
--   * money/rating columns are double precision: the previous MongoDB schema
--     stored JS numbers, and the API computes prices in JS — keeping the same
--     semantics avoids float↔string conversions on every row.
--   * jsonb for documents that were embedded objects in Mongo (addresses,
--     specifications, variants, media, guest info).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ─── Users ────────────────────────────────────────────────────────────────────
CREATE TABLE users (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Clerk owns authentication; this links the local profile/role to the
    -- Clerk user id (sub claim of the verified session token).
    clerk_user_id   text UNIQUE,
    name            text NOT NULL,
    email           text NOT NULL UNIQUE,
    role            text NOT NULL DEFAULT 'customer'
                    CHECK (role IN ('customer', 'seller', 'admin')),
    avatar          text NOT NULL DEFAULT 'https://api.dicebear.com/7.x/avataaars/svg?seed=default',
    phone           text,
    address         jsonb NOT NULL DEFAULT '{}'::jsonb,
    wishlist        uuid[] NOT NULL DEFAULT '{}',
    recently_viewed jsonb NOT NULL DEFAULT '[]'::jsonb, -- [{ product, viewedAt }]
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX users_role_idx ON users (role);
CREATE INDEX users_created_at_idx ON users (created_at DESC);

-- ─── Stores ───────────────────────────────────────────────────────────────────
CREATE TABLE stores (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id       uuid NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
    name           text NOT NULL,
    description    text NOT NULL DEFAULT '',
    logo           text NOT NULL DEFAULT 'https://via.placeholder.com/150',
    banner         text NOT NULL DEFAULT 'https://via.placeholder.com/1200x300',
    category       text NOT NULL,
    address        jsonb NOT NULL DEFAULT '{}'::jsonb,
    contact        jsonb NOT NULL DEFAULT '{}'::jsonb,
    rating         double precision NOT NULL DEFAULT 0,
    review_count   integer NOT NULL DEFAULT 0,
    is_active      boolean NOT NULL DEFAULT true,
    is_verified    boolean NOT NULL DEFAULT false,
    business_hours text NOT NULL DEFAULT '',
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX stores_active_created_idx ON stores (is_active, created_at DESC);
CREATE INDEX stores_active_rating_idx  ON stores (is_active, rating DESC);

-- ─── Products ─────────────────────────────────────────────────────────────────
CREATE TABLE products (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id            uuid NOT NULL REFERENCES stores (id) ON DELETE CASCADE,
    seller_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name                text NOT NULL,
    description         text NOT NULL,
    price               double precision NOT NULL CHECK (price >= 0),
    compare_at_price    double precision CHECK (compare_at_price IS NULL OR compare_at_price >= 0),
    category            text NOT NULL,
    subcategory         text,
    brand               text,
    images              text[] NOT NULL DEFAULT '{}',
    stock               integer NOT NULL DEFAULT 0 CHECK (stock >= 0),
    rating              double precision NOT NULL DEFAULT 0,
    review_count        integer NOT NULL DEFAULT 0,
    tags                text[] NOT NULL DEFAULT '{}',
    specifications      jsonb NOT NULL DEFAULT '{}'::jsonb,
    variants            jsonb NOT NULL DEFAULT '[]'::jsonb,
    low_stock_threshold integer NOT NULL DEFAULT 10,
    bulk_discounts      jsonb NOT NULL DEFAULT '[]'::jsonb,
    is_active           boolean NOT NULL DEFAULT true,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CHECK (rating >= 0 AND rating <= 5)
);
CREATE INDEX products_seller_stock_idx  ON products (seller_id, stock);
CREATE INDEX products_seller_idx        ON products (seller_id);
CREATE INDEX products_category_idx      ON products (category);
CREATE INDEX products_store_idx         ON products (store_id);
CREATE INDEX products_active_cat_price_idx ON products (is_active, category, price);
CREATE INDEX products_active_rating_idx   ON products (is_active, rating DESC);
CREATE INDEX products_active_created_idx  ON products (is_active, created_at DESC);
-- Replaces the MongoDB text index on { name, description, brand }
CREATE INDEX products_search_idx ON products
    USING gin (to_tsvector('english',
        name || ' ' || description || ' ' || COALESCE(brand, '')));

-- ─── Orders ───────────────────────────────────────────────────────────────────
CREATE TABLE orders (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    order_number    text UNIQUE,
    customer_id     uuid REFERENCES users (id) ON DELETE SET NULL,
    guest_info      jsonb NOT NULL DEFAULT '{}'::jsonb,
    shipping_address jsonb NOT NULL DEFAULT '{}'::jsonb,
    payment_method  text NOT NULL CHECK (payment_method IN ('card', 'paypal', 'cod')),
    payment_status  text NOT NULL DEFAULT 'pending'
                    CHECK (payment_status IN ('pending', 'completed', 'failed')),
    items_price     double precision NOT NULL,
    shipping_price  double precision NOT NULL DEFAULT 0,
    tax_price       double precision NOT NULL DEFAULT 0,
    total_price     double precision NOT NULL,
    status          text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'processing', 'shipped', 'delivered', 'cancelled')),
    delivered_at    timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX orders_customer_idx      ON orders (customer_id);
CREATE INDEX orders_status_created_idx ON orders (status, created_at DESC);
CREATE INDEX orders_payment_status_idx ON orders (payment_status);

-- Line items were an embedded array; Postgres normalises them so seller/analytics
-- queries stop unwinding arrays, while name/price are snapshotted at purchase.
CREATE TABLE order_items (
    order_id   uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    line_no    integer NOT NULL,
    product_id uuid REFERENCES products (id) ON DELETE SET NULL,
    store_id   uuid REFERENCES stores (id) ON DELETE SET NULL,
    seller_id  uuid REFERENCES users (id) ON DELETE SET NULL,
    name       text,
    price      double precision,
    quantity   integer NOT NULL CHECK (quantity >= 1),
    image      text,
    PRIMARY KEY (order_id, line_no)
);
CREATE INDEX order_items_store_idx   ON order_items (store_id);
CREATE INDEX order_items_product_idx ON order_items (product_id, order_id);
CREATE INDEX order_items_seller_idx  ON order_items (seller_id);

-- ─── Reviews ──────────────────────────────────────────────────────────────────
CREATE TABLE reviews (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    product_id           uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    rating               integer NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment              text NOT NULL CHECK (char_length(comment) <= 1000),
    is_verified_purchase boolean NOT NULL DEFAULT false,
    media                jsonb NOT NULL DEFAULT '[]'::jsonb, -- [{url,type,key}]
    helpful_votes        integer NOT NULL DEFAULT 0,
    created_at           timestamptz NOT NULL DEFAULT now(),
    UNIQUE (product_id, user_id)
);
CREATE INDEX reviews_product_idx ON reviews (product_id, created_at DESC);

-- ─── Settings (singleton row) ─────────────────────────────────────────────────
CREATE TABLE settings (
    id                 boolean PRIMARY KEY DEFAULT true CHECK (id),
    tax_rate           double precision NOT NULL DEFAULT 8 CHECK (tax_rate BETWEEN 0 AND 100),
    shipping_fee       double precision NOT NULL DEFAULT 10 CHECK (shipping_fee >= 0),
    fixed_fee_per_order double precision NOT NULL DEFAULT 2 CHECK (fixed_fee_per_order >= 0),
    updated_by         uuid REFERENCES users (id) ON DELETE SET NULL,
    updated_at         timestamptz NOT NULL DEFAULT now()
);

-- ─── Chat messages ────────────────────────────────────────────────────────────
CREATE TABLE messages (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    room_id    text NOT NULL,
    sender_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    text       varchar(500) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX messages_room_created_idx ON messages (room_id, created_at DESC);
